import type { ReactNode } from 'react';

import { FilterValue, Option } from 'models/Filters';

import { Chip, ChipsContainer } from './ChipsSelect.styles';

interface ChipsSelectProps {
  options: Option[];
  value: string | string[];
  onChange: (option: Option) => void;
  multiple?: boolean;
  disabled?: boolean;
  label?: string;
  dataTestId?: string;
  renderOptionLabel?: (option: Option) => ReactNode;
  variant?: 'default' | 'rounded';
}

export const ChipsSelect: React.FC<ChipsSelectProps> = ({
  options,
  value,
  onChange,
  disabled = false,
  dataTestId,
  renderOptionLabel,
  variant = 'default',
}) => {
  const isSelected = (optionValue: FilterValue) => {
    if (Array.isArray(value)) {
      return value.includes(optionValue as string);
    }
    return value === optionValue;
  };

  return (
    <ChipsContainer data-testid={dataTestId}>
      {options.map((option) => {
        const isDisabled = Boolean(disabled || option.isDisabled);

        return (
          <Chip
            key={option.value}
            type="button"
            $selected={isSelected(option.value)}
            onClick={() => onChange(option)}
            data-testid={
              dataTestId ? `${dataTestId}-option-${option.value}` : undefined
            }
            $isDisabled={isDisabled}
            disabled={isDisabled}
            $rounded={variant === 'rounded'}
            data-variant={variant}
          >
            {renderOptionLabel ? renderOptionLabel(option) : option.label}
          </Chip>
        );
      })}
    </ChipsContainer>
  );
};
